        content: `> 「太阳病」，项背强几几，及汗出，恶风者，「桂枝加葛根汤」主之。 **项背强几几**：脖子绷得很紧，项背强几几表示此处的代谢循环系统不是很正常。平常感冒进来的时候，桂枝汤就可以了，但是肌肉里面有一定的水，表水有时候没办法排出去，就会陷在肌肉里面，等于不正常的水在肌肉里，就会硬绑绑的，感觉背后到颈部冰冷冷的。 **葛根的作用**：把水提升上来，然后靠桂枝把水排出去变成汗，这样子肌肉中的水就能正常代`,
