        content: `> 发汗后，身疼痛，脉沉迟者，「桂枝」加「芍药」、「生姜」各一两，「人参」三两，「新加汤」主之。 **倪海厦解读**： - 发了汗，身体还在痛，照理说伤寒的时候，因为寒束在表上，所以身体会痛 - 发 了汗身体还在痛为什么？就是因为处方开太过了 - 发汗的药开太强了，这个疼痛是因为津液伤到了，孙络没有津液干掉了造成的 - 病人的脉沉迟，沉代表病在里，迟代表寒 - 这时候如何把发太过的津液补回来，就是`,
