        content: `> 发汗后，不可更行「桂枝汤」。汗出而喘，无大热者，可与「麻黄杏仁甘草石膏汤」主之。 **倪海厦解读**： - 这条是讲发汗以后的辨症 - 如果病人已经发汗了，为什么不能再给桂枝汤？ - 汗出而喘，无大热者，可与「麻黄杏仁甘草石膏汤」主之，就是麻杏甘石汤 - 平常在临床看的时候，如果一个人得病，得到太阳证 - 桂枝汤证或麻黄汤证或葛根汤证 - 病人星期三得病的，本来只是感冒，星期六才来医 - 病的`,
