        content: `> 发汗过多，其人叉手自冒心，心下悸欲得按者，「桂枝甘草汤」主之。 **倪海厦解读**： - 发汗发太多的，一定是麻黄汤 - 麻黄汤把胸腔的水都发汗掉了 - 并使肚脐下面，下焦的水往上冲 - 冲上来的力量太大的时候，病人就感觉到心下悸 - 为什么叉手自冒心？就是很难过想压下去 - 所以就是心下悸，按着就比较舒服 **桂枝甘草汤方**： - 桂枝四两去皮，甘草二两炙 - 右二味，以水三升，煮取一升，`,
