        content: `> 发汗后，其人脐下悸者，欲作「奔豚」，「茯苓桂枝甘草大枣汤」主之。 **倪海厦解读**： - 六九条的发汗发太多的，一定是麻黄汤 - 麻黄汤把胸腔的水都发汗掉了，并使肚脐下面，下焦的水往上冲 - 冲上来的力量太大的时候，病人就感觉到心下悸 - 为什么叉手自冒心？就是很难过想压下去，所以就是心下悸，按着就比较舒服 - 六九条和七十条，这两条都是发汗以后，但是发汗的力量不一样 - 六九条是麻黄汤发汗`,
