        content: `> 发汗后，腹胀满者，「厚朴生姜半夏甘草人参汤」主之。 **倪海厦解读**： **虚胀vs实胀**： - 有两种情形腹胀满，一种是虚胀，一种是实胀 - 虚胀的病人感觉是喜按，实胀是拒按 - 我们可以按天枢穴，实胀就是大便堵到了 - 虚胀是肠子的瓦斯气在里面，就是胀气很多在里面 - 所以厚朴生姜半夏甘草人参汤病人吃下去以后 - 病人会一直在嗳气，一直在放屁，然后肚子就消掉了 - 所以虚胀的时候是厚朴`,
