        content: `> 「伤寒」，若吐若下后，心下逆满，气上冲胸，起则头眩，脉沉紧，发汗则动经，身为振振摇者，「茯苓桂枝白朮甘草汤」主之。 **倪海厦解读**： - 伤寒，如果吐了又大下，肠胃就伤到了 - 结果心下逆满，就是胃的地方感觉到胀满 - 气往上冲，因为这水没能气化上来，是水停在这里 - 呼吸的时候，气会往回逆 - 一般来说，横膈膜会下降，气才会充满 - 吐气的时候，横膈膜会上升 - 结果横膈膜都是水，它根本`,
