        title: "胸痹心痛短气病脉证并治第九",
        content: `什么叫「平人无寒热」?就是正常的人，也没有什么特别的怕冷或怕热，就是没有寒热的症状。忽然会感觉到呼吸呼不过来，又「不足以息」，就是呼吸很短促。 > 正常人，没有什么寒热，就是一走路，常常会呼吸很短，感觉呼不过来气，这种就是实证。 从这点我们就可以判定，有东西堵到了，就是实症，这就是区分虚实的方法。我们在胸痹这一篇里面介绍到的通通是治疗虚症的，没有治疗实症的。 > 胸为阳，腹为阴，为什么这么分？阳就`,
