        id: "shanghan-262",
        title: "五藏风寒积聚病脉证并治第十一",
        content: `> 一般人体虚的时候，风就容易进去，会趁虚而入。 > 这些不需要记，看病的时候自然就知道了。比如这个两胁苦满，少阳证，小柴胡汤，头目润动，眼睛在那边动来动去，肝开窍在眼睛，风在里面走的时候，头目就会动，晃动晃动，像帕金森症，头部会动。 > 肝苦急，急食甘以缓之，所以令人嗜甘，就会自然而然想去吃甜的。 肝中风，中风是热症。 风热会进入肝脏里面，主要是因为表症没有被治好造成的。如果病在表时就被治好了，`,
