        id: "shanghan-284",
        title: "痰饮欬嗽病脉证并治第十二",
        content: `这条辨是指肝心脾肺肾五个内脏如果有水的话，我们该如何去分辨水在哪个脏腑。因为内伤是情志病，所以喜伤心、思伤脾、怒伤肝、忧伤肺、恐伤肾，因各种不同情志造成的水病。 如果是心受伤，就会在心下胃的地方会绷起来,「坚筑短气」,硬硬的顶在胃的地方，让病人无法正常呼吸，这是心脏有水。「恶水不欲饮」因为水在上面，就是所谓「水气凌心」，我们心脏本身是火，根本不该受水，因为心很热，当有水停在膈膜的时候，我们呼吸横膈`,
