        id: "shanghan-330",
        title: "消渴小便不利淋病脉证治第十三",
        content: `> 心中讲的就是胃，很热燥热，疼。很饿，吃东西又吐，病在胃。症状上看，可能有宿食堵着，但是用大黄甘草汤攻下，清完病人没有胃很舒服，没有开始吃东西，也不会吐了，但是利不肯止，病还在，代表不是宿食。 病在厥阴时会出现消渴之症，而消渴之症会让病人感到胃里又痛又燥热，感觉到肚子很饿，但是无法吃东西，因为一吃食物就会呕吐，看起来好像是肠胃里面有宿食造成的，于是你使用攻下的药物，想将之清除掉，但是病人并不是因`,
