        id: "shanghan-538",
        title: "趺蹶手指臂肿转筋狐疝蚘虫病脉证治第十九",
        content: `> 虫，蛔虫，肚子里的寄生虫。 「问曰:病腹痛有虫，其脉何以别之?」病人肚子里面有虫，你怎么用查脉就知道病人身体里面有虫?张仲景说:腹中痛,病人有肚子痛，当然不只是肚痛，病人有虫的话一定有胃痛。 「腹中痛，其脉当沉」照理说腹痛是脉沉弦，结果你摸病人的脉是洪而且大。尤其小孩子，小孩子肚子里面常常有虫，肚子痛时你摸他的脉，如果脉沉就知道肚子痛是里寒造成，这是小建中汤证，结果摸到脉反而是洪大，就知道肚子`,
