        title: "痉湿暍病脉证治法第二",
        content: `> 光是把这个湿讲完，风湿关节炎，痛风，皮肤表面的湿疹、荨麻疹，蚊虫的咬伤，都能讲完。 > 沉脉，病在里。细，就是被东西束到，是寒。这种脉常常可以摸到，只要摸到一次，第二次一摸你就知道他关节开始痛。 中湿就是中焦里湿很盛，叫中湿，也叫做湿痹。湿痹的症候有哪些呢?怎么知道有湿痹? 病人的主症,第一个是小便不利，大便反快这个时候当利小便。 > 大便很喜欢湿，大肠喜湿，恶燥。如果一个人一天五六次厕所大便`,
