        id: "shanghan-770",
        title: "血痹虚劳病脉并治第六",
        content: `酸枣仁二升 | 甘草一两 | 知母、茯苓各二两 | 芎藭一两 上五味，以水八升，煮酸枣仁，得六升，内诸药，煮取三升，分温三服。 > 先煮酸枣仁，再煮其他的。 酸枣仁汤多是用在一般老年人身上，睡觉只能睡两三个小时后就醒过来，然后再也睡不着，这就是虚劳不能眠的症状，此时就可以用酸枣仁汤。 > 年龄大了，身体衰弱下去，产生的失眠，就是酸枣仁汤。大病初愈，身体虚弱，失眠，也是。 酸枣仁汤中有甘草、知母、茯`,
