        title: "肺痿肺痈咳嗽上气病脉证治第七",
        content: `> 这个最容易治疗，发汗呢，就可以治好。 如果病人出现「喘而躁」就称为「肺胀」。中医所谓的肺胀临床看就是西医讲的肺气肿。 肺气肿的原因很多，比如我们居住在工厂附近，又刚好是棉花工厂，或刚好住在地毯工厂旁边，棉絮很多，或是住在空气污浊的地方，像是煤炭工厂旁边等，以前很多矿工得到肺气肿，都是因为空气里面不干净才得到。还有老师们写黑板产生的粉笔灰，老师吸多了也会造成肺气肿。 此处的肺胀就是现代的肺气肿，`,
