        title: "天纪·地脉道 六十四卦与阳宅",
        content: `每一卦象对应不同的阳宅格局，影响居住者的事业、婚姻、健康等。 **乾卦**（天）：乾卦可行，但却居坤位，始成破格，终必败。故如有一女人家，只要事业，只要健康，对于婚姻因前次之失败... **屯卦**：有一运用，在家族事业，世代交替时，父必使次子继位长子失宠，其运如此，吾人观命时，必可发现，次子之事业必优于长子，才智能力超越长子。 **需卦**：婚事延后七年，且单岁婚。如逢八字中，喜庆逢凶，必入宗教`,
