        content: `**中医理论基础：** - 女子二七天癸至，月事以时下，七七四十九天癸竭 - 乳房有十一条经络汇集（正经八条+奇经三条），只有一个红绿灯（心脏）控制——如同十一条马路交会的路口，容易出事 - **奶水就是月经**：两大证据——(1)喂母乳期间无月经，但卵子仍每月排出，故仍会怀孕；(2)结扎后无卵入子宫，仍有月经。说明月经与奶水同源，与卵子无关 - 奶水源自脾脏：土生金，金色白，脾土从小肠取得食物精`,
